package com.littlemakers.village.nativeapp;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;

/** Offline adventure lobby, rescue and aquarium around the existing learning destinations. */
public final class AdventureActivity extends Activity {
 final AdventureState expedition=new AdventureState();final HabitatState habitat=new HabitatState();
 private AnimatedToyDock dock;private AdventureSurface island;private HabitatSurface aquarium;private LinearLayout root,body;private ThemeManager theme;private SoundEngine sound;private GameDatabase db;private PlayerWallet wallet;private ProgressManager progress;private TextView objective;private Button action;private String screen="island";private boolean paused,resumedOnce,destroyed;
 private final Handler ui=new Handler(Looper.getMainLooper());
 private final Runnable refresh=new Runnable(){public void run(){if(!paused&&screen.equals("island")){updateMission();ui.postDelayed(this,350);}}};
 @Override public void onCreate(Bundle b){super.onCreate(b);db=GameDatabase.create(this);wallet=new PlayerWallet(db);progress=new ProgressManager(db);sound=new SoundEngine(this);expedition.restore(getSharedPreferences("adventure",0).getString("expedition",""));habitat.restore(getSharedPreferences("adventure",0).getString("habitat",""));if(expedition.bridge>=3)wallet.creativeCompletion("adventure-0");screen=b==null?"island":b.getString("screen","island");show(screen);if(Build.VERSION.SDK_INT>=33)Api33.register(this);}
 static final class Api33{static void register(AdventureActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::back);}}
 private int dp(float n){return theme.dp(n);}private boolean reduced(){return getSharedPreferences("family",0).getBoolean("reduce_motion",false)||android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}
 private TextView text(String label,int size,boolean bold){TextView v=new TextView(this);v.setText(label);v.setTextSize(size);v.setTextColor(theme.text);v.setTypeface(theme.font(bold));v.setPadding(dp(6),dp(6),dp(6),dp(6));return v;}
 private Button button(String label,Runnable task){Button v=new Button(this);v.setText(label);v.setAllCaps(false);v.setTextSize(16);v.setTextColor(theme.text);v.setTypeface(theme.font(true));v.setMinHeight(dp(64));v.setBackground(theme.panel(true));v.setElevation(dp(3));v.setOnClickListener(w->{sound.tap();w.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);task.run();});ThemeManager.bindPress(v);return v;}
 private void add(Button b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(3),dp(5),dp(3),dp(5));body.addView(b,p);}
 private void persist(){getSharedPreferences("adventure",0).edit().putString("expedition",expedition.save()).putString("habitat",habitat.save()).apply();}
 private void base(String title){if(dock!=null){dock.stop();dock=null;}ui.removeCallbacks(refresh);persist();if(island!=null){island.onPause();island=null;}if(aquarium!=null){aquarium.onPause();aquarium=null;}theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(button("⌂",()->show("island")),new LinearLayout.LayoutParams(dp(64),dp(64)));TextView h=text(title,23,true);h.setGravity(Gravity.CENTER);top.addView(h,new LinearLayout.LayoutParams(0,-2,1));Button parent=button("⚙",()->legacy("parents"));parent.setContentDescription("Parent settings, protected by parent PIN");top.addView(parent,new LinearLayout.LayoutParams(dp(64),dp(64)));root.addView(top);
  ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(8),dp(12),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout nav=new LinearLayout(this);String[]names={"⌂\nIsles","≈\nAquarium","✦\nAlbum","☺\nWardrobe"},routes={"island","habitat","album","wardrobe"};for(int i=0;i<4;i++){final String route=routes[i];Button tab=button(names[i],()->show(route));tab.setBackgroundColor(screen.equals(route)?theme.mint:theme.background);tab.setElevation(0);tab.setTextSize(14);nav.addView(tab,new LinearLayout.LayoutParams(0,dp(64),1));}root.addView(nav);
 }
 private boolean graphics(){return ((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion>=0x20000;}
 void show(String route){screen=route;if(route.equals("wardrobe")){legacy("friend");screen="island";return;}if(route.equals("habitat")){habitat();return;}if(route.equals("album")){album();return;}island();}
 private void updateMission(){if(objective==null||!screen.equals("island"))return;int seeds=expedition.seeds();String mission=expedition.bridge>=3?"A bridge for our turtle! Your aquarium is ready to visit.":"Rescue trail · "+seeds+" / 3 seeds found · "+expedition.bridge+" / 3 bridge pieces grown";if(!mission.contentEquals(objective.getText()))objective.setText(mission);String next=expedition.action();if(!next.contentEquals(action.getText()))action.setText(next);}
 void island(){screen="island";base("Wonder Isles");
  // The world owns the available height: no scroll container can hide it behind controls.
  root.removeView((View)body.getParent());FrameLayout stage=new FrameLayout(this);root.addView(stage,1,new LinearLayout.LayoutParams(-1,0,1));
  objective=text("Tap the island to walk",15,true);objective.setBackground(theme.panel(false));FrameLayout.LayoutParams status=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP);status.setMargins(dp(12),dp(8),dp(12),0);
  if(graphics()){island=new AdventureSurface(this,expedition,theme.dark,reduced(),wallet.skinColor(),wallet.equipped("accessory"),new AdventureSurface.Listener(){public void changed(int event){if(paused||destroyed||isFinishing()||!screen.equals("island"))return;persist();if(event==1)sound.note(expedition.seeds());if(event==2)sound.note(expedition.bridge);if(event==3){wallet.creativeCompletion("adventure-0");sound.win();}updateMission();}public void unavailable(){if(island!=null){island.onPause();stage.removeView(island);island=null;objective.setText("Choose a toy below to play");}}});stage.addView(island,new FrameLayout.LayoutParams(-1,-1));}
  stage.addView(objective,status);
  LinearLayout tools=new LinearLayout(this);String[]icons={"✦","◉","↺"};String[]descriptions={"Follow the next clue","Map or follow camera","Recenter camera"};for(int i=0;i<3;i++){final int pick=i;Button tool=button(icons[i],()->{if(island==null)return;if(pick==0)island.clue();else if(pick==1){island.overview=!island.overview;island.requestRender();}else island.recenter();});tool.setContentDescription(descriptions[i]);tools.addView(tool,new LinearLayout.LayoutParams(dp(64),dp(64)));}FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(-2,dp(64),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);tp.bottomMargin=dp(84);stage.addView(tools,tp);
  action=button("Follow the next clue",()->{if(expedition.bridge>=3&&(expedition.nearBridge()||expedition.z<-3.2f)){show("habitat");return;}if(expedition.nearSeed()>=0||expedition.nearBridge()){if(island!=null)island.action();return;}int place=expedition.nearPlace();if(place>=0){learning(VillageSceneState.ROUTES[place]);return;}if(island!=null)island.clue();});FrameLayout.LayoutParams ap=new FrameLayout.LayoutParams(-1,dp(64),Gravity.BOTTOM);ap.setMargins(dp(16),0,dp(16),dp(12));stage.addView(action,ap);
  dock=new AnimatedToyDock(this,theme,reduced(),index->{sound.tap();if(index<5)learning(VillageSceneState.ROUTES[index]);else startActivity(new Intent(this,QuestActivity.class));});root.addView(dock,2,new LinearLayout.LayoutParams(-1,dp(176)));updateMission();ui.post(refresh);
 }
 private Button decorationButton(int item){boolean unlocked=wallet.stars()>=HabitatState.STARS[item];return button(HabitatState.NAMES[item]+(unlocked?" · place":" · "+HabitatState.STARS[item]+" stars"),()->{if(habitat.place(item,wallet.stars())){persist();if(aquarium!=null)aquarium.requestRender();sound.note(item%3);objective.setText(HabitatState.NAMES[item]+" placed in spot "+(habitat.selected+1)+".");}else objective.setText("Explore learning activities to unlock this decoration. Your starter pieces are always free.");});}
 void habitat(){screen="habitat";base("My living aquarium");body.addView(text("Choose a spot, then place a shelter or decoration.",18,true));objective=text("Spot "+(habitat.selected+1)+" · "+habitat.count()+" / 9 spaces made yours",17,false);body.addView(objective);HorizontalScrollView tray=new HorizontalScrollView(this);LinearLayout pieces=new LinearLayout(this);for(int item=0;item<HabitatState.NAMES.length;item++)pieces.addView(decorationButton(item),new LinearLayout.LayoutParams(dp(150),dp(80)));tray.addView(pieces);body.addView(tray);FrameLayout viewport=new FrameLayout(this);body.addView(viewport,new LinearLayout.LayoutParams(-1,dp(360)));if(graphics()){aquarium=new HabitatSurface(this,habitat,theme.dark,reduced(),new HabitatSurface.Listener(){public void selected(int slot){objective.setText("Spot "+(slot+1)+" selected. Choose a decoration from the tray.");}public void unavailable(){if(aquarium!=null){aquarium.onPause();viewport.removeView(aquarium);aquarium=null;viewport.addView(text("Your aquarium layout is saved. Spot and decoration buttons remain available.",17,false));}}});viewport.addView(aquarium,new FrameLayout.LayoutParams(-1,-1));}
  for(int row=0;row<3;row++){LinearLayout line=new LinearLayout(this);for(int col=0;col<3;col++){final int slot=row*3+col;Button spot=button("Spot "+(slot+1),()->{habitat.select(slot);if(aquarium!=null)aquarium.requestRender();objective.setText("Spot "+(slot+1)+" selected.");});line.addView(spot,new LinearLayout.LayoutParams(0,dp(64),1));}body.addView(line);}
  add(button("Clear selected spot",()->{habitat.clear();persist();if(aquarium!=null)aquarium.requestRender();objective.setText("Spot "+(habitat.selected+1)+" is ready for a new idea.");}));body.addView(text(wallet.stars()+" stars · Decorations unlock predictably. No purchases or random prizes.",15,false));
 }
 void album(){screen="album";base("Adventure Album");body.addView(text("Your discoveries stay. No streaks to lose.",21,true));body.addView(text((expedition.bridge>=3?"✓ ":"○ ")+"Grow the turtle bridge · collect three seeds and plant them",18,false));body.addView(text((learningCount()>0?"✓ ":"○ ")+"Explore a learning activity · "+learningCount()+" first completions saved",18,false));body.addView(text((habitat.count()>=3?"✓ ":"○ ")+"Make three aquarium spaces your own · "+habitat.count()+" placed",18,false));add(button("Continue the rescue trail",()->show("island")));add(button("Choose a learning game",()->legacy("playroom")));add(button("Build in my aquarium",()->show("habitat")));body.addView(text("Your next ideas",21,true));String[]choices={"Count a collection","Make a picture","Help a story friend"};for(int i=0;i<3;i++){final int pick=i;add(button(choices[i],()->{if(pick==0)legacy("playroom");else learning(pick==1?"paint":"story");}));}}
 private int learningCount(){try(android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM completion WHERE game_id NOT LIKE 'creative-adventure-%'",null)){return c.moveToFirst()?c.getInt(0):0;}}
 private void learning(String route){persist();startActivity(new Intent(this,CreativeActivity.class).putExtra("destination",route).putExtra("adventure_return",true));}
 private void legacy(String route){persist();startActivity(new Intent(this,MainActivity.class).putExtra("destination",route).putExtra("adventure_return",true));}
 private void back(){if(!screen.equals("island"))show("island");else new AlertDialog.Builder(this,theme.dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("Take a little break?").setMessage("Your island and aquarium are saved.").setNegativeButton("Keep exploring",null).setPositiveButton("Rest now",(d,w)->finish()).show();}
 @Override public void onBackPressed(){back();}
 @Override protected void onPause(){paused=true;if(dock!=null)dock.stop();ui.removeCallbacks(refresh);if(island!=null)island.onPause();if(aquarium!=null)aquarium.onPause();persist();sound.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();paused=false;if(!resumedOnce){resumedOnce=true;return;}if(theme!=null){android.content.SharedPreferences saved=getSharedPreferences("adventure",0);if(saved.contains("expedition"))expedition.restore(saved.getString("expedition",""));else expedition.reset();if(saved.contains("habitat"))habitat.restore(saved.getString("habitat",""));else habitat.reset();if(expedition.bridge>=3)wallet.creativeCompletion("adventure-0");show(screen);}}
 @Override protected void onSaveInstanceState(Bundle b){persist();super.onSaveInstanceState(b);b.putString("screen",screen);}
 @Override protected void onDestroy(){destroyed=true;ui.removeCallbacks(refresh);sound.stop();db.close();super.onDestroy();}
}
